  const ground=kind==='night'?'#0B1030':'#3A4A62';
  let tw5='';lots.slice(0,5).forEach(([n,col,f,k],i)=>{const x=10+i*30;let fl=k==='mon'?rep('dark',f):grow(f,k==='top'?0:7);if(k==='sh')fl=grow(f,7,{[f-4]:'shield'});if(k==='now')fl=grow(f,5);if(i===4)fl=rep('dark',6);const cc=i===4?'#8A93A0':col;tw5+=`${tw(cc,{x,base:132,w:17,fh:3.5,dx:6,dy:4,floors:fl,windows:2,today:k==='now',wW:2,wH:1.1})}${k==='top'?flagCap(x,132-f*3.5,17,6,4).replace('-18l13,5l-13,5','-9l7,2.5l-7,2.5'):''}`});
