function endedChallenge(reached){
  const n=reached?80:62,total=80,fhh=2.4,base=250;
  const lm=tw('#FF8A5C',{x:150,base,w:80,fh:fhh,dx:24,dy:13,floors:lmFl(n,'dark'),windows:4,wW:3,wH:1.2,today:false});
  const cap=reached?flagCap(150,base-n*fhh,80,24,13):'';
  const ghost=reached?'':`<path d="M150,${base-n*fhh}h80v${-(total-n)*fhh}h-80Z M230,${base-n*fhh}l24,-13v${-(total-n)*fhh}l-24,13" fill="none" stroke="#fff" stroke-opacity=".5" stroke-dasharray="3 3" stroke-width="1"/>`;
  const lab=reached?'':`<text x="190" y="${base-n*fhh-(total-n)*fhh-22}" text-anchor="middle" font-size="13" font-weight="800" fill="#fff" fill-opacity=".85" font-family="Nunito">Ended at floor ${n}</text>`;
  const rows=[['You','#FF8A5C',reached?29:24],['Maya','#38BDF8',reached?21:17],['Alex','#F2C14E',reached?18:12],['Dev','#A78BFA',reached?12:9]];
  const mx=rows[0][2];
  R.innerHTML=`<div style="position:absolute;inset:0;overflow:hidden"><div style="padding:30px 20px 0"><div style="font-size:17px;font-weight:700">‹&nbsp; Challenges</div><h1 style="font-size:30px;margin-top:12px">30 days of reading</h1><div style="display:flex;align-items:center;gap:10px;margin-top:4px"><span style="color:#A3ADB8;font-size:14px;flex:1">Private · Ended Nov 8</span>${endedChip(reached?'Target reached':'Ended',reached)}</div></div>
   <svg width="390" height="270" style="position:absolute;top:152px;left:0"><g opacity=".92">${dusk(390,270,'d3')}${ghost}${lm}${cap}${lab}</g></svg>
   <div style="position:absolute;top:436px;left:20px;right:20px"><div style="display:flex;gap:8px">${[['Built',`${n} of ${total}`],['Your part',`${rows[0][2]} floors`],['Ran','30 days']].map(([l,v])=>`<div style="flex:1;background:#161B21;border-radius:16px;padding:12px"><div style="color:#A3ADB8;font-size:13px;font-weight:700">${l}</div><div style="font-size:19px;font-weight:800;margin-top:4px">${v}</div></div>`).join('')}</div>
   <div style="color:#A3ADB8;font-size:15px;font-weight:700;margin:14px 0 6px">Who built what</div>${rows.map(([nm,c,v])=>`<div style="display:flex;align-items:center;gap:10px;height:32px"><i style="width:11px;height:11px;border-radius:50%;background:${c};display:block"></i><span style="width:44px;font-weight:700;font-size:15px">${nm}</span><div style="flex:1;height:9px;border-radius:5px;background:#1E252D;overflow:hidden"><div style="width:${v/mx*100}%;height:100%;background:${c}"></div></div><span style="width:24px;text-align:right;font-weight:800;color:#A3ADB8">${v}</span></div>`).join('')}
   <div style="background:#161B21;border-radius:14px;padding:12px 14px;margin-top:12px;color:#C9CED4;font-size:14px;line-height:1.45">${reached?'You built it all together. This landmark now stands on your skyline as a finished tower.':'The landmark stays at the height you built together and stands on your skyline as a finished tower.'}</div></div></div>${tabBar(2)}`;
}
if(S3==='ce-done')endedChallenge(true);
