const nRow=(k,title,body,time,unread,acts,chipHtml)=>{const [lab,c]=NCAT[k];return `<div style="display:flex;gap:12px;padding:14px 0;border-bottom:1px solid #1F262E;align-items:flex-start"><div style="width:44px;height:44px;border-radius:14px;background:${c}26;display:flex;align-items:center;justify-content:center;flex:0 0 44px">${nIcon(k,c)}</div><div style="flex:1;min-width:0"><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:11px;font-weight:800;letter-spacing:.7px;color:${c}">${lab}</span><span style="font-size:12px;color:#A3ADB8">${time}</span></div><div style="font-size:15.5px;font-weight:${unread?800:600};margin-top:2px;${unread?'':'color:#C9CED4'}">${title}</div><div style="font-size:13.5px;color:#A3ADB8;line-height:1.4;margin-top:2px">${body}</div>${chipHtml?`<div style="margin-top:8px;display:inline-block;height:28px;line-height:28px;padding:0 12px;border-radius:14px;background:${c}26;color:${c};font-weight:800;font-size:12.5px">${chipHtml}</div>`:''}${acts?`<div style="display:flex;gap:6px;margin-top:8px">${acts.map((a,i)=>`<div style="height:32px;padding:0 13px;border-radius:16px;display:flex;align-items:center;font-weight:800;font-size:13px;${i===0?`background:${c};color:#0b0f14`:'border:1.5px solid #2F3944;color:#F2F4F6'}">${a}</div>`).join('')}</div>`:''}</div>${unread?`<i style="width:9px;height:9px;border-radius:50%;background:${c};display:block;margin-top:22px"></i>`:'<i style="width:9px;display:block"></i>'}</div>`};
const nChips=(on)=>{const L=[['All',3],['Friends',1],['Shared habits',1],['Challenges',1],['Reminders',0],['Summaries',0]];return `<div style="overflow:hidden"><div style="display:flex;gap:8px;white-space:nowrap;padding:0 20px;width:max-content;${on>=3?'transform:translateX(-110px);':''}">${L.map(([t,n],i)=>`<div style="height:38px;border-radius:19px;padding:0 14px;display:flex;align-items:center;gap:7px;font-weight:700;font-size:14px;${i===on?'background:#2B2717;border:1.5px solid #F2C14E;color:#F2F4F6':'background:#1E252D;color:#C9CED4;border:1.5px solid transparent'}">${t}${n?`<span style="min-width:18px;height:18px;border-radius:9px;background:#F2C14E;color:#1b1608;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center;padding:0 5px">${n}</span>`:''}</div>`).join('')}</div></div>`};
const nHead=`<div style="display:flex;align-items:center;justify-content:space-between;padding:30px 20px 12px"><div style="width:44px;height:44px;border-radius:22px;background:#1E252D;display:flex;align-items:center;justify-content:center;font-size:20px;color:#A3ADB8">×</div><div style="font-size:17px;font-weight:800">Notifications</div><div style="width:44px;height:44px;display:flex;align-items:center;justify-content:center">${ico('check-all',22,'#A3ADB8')}</div></div>`;
